"""Mobile"""
from __future__ import absolute_import
from builtins import range
from time import sleep
from taf.ul.trs_e2e_fw.lib.call_utils.ue import UE
from taf.ul.trs_e2e_fw.lib.call_utils.te_id import TeId
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf import Iperf
from taf.ul.trs_e2e_fw.lib.call_utils.exceptions import ProfileNotPassedException, IpNotFoundException, TEIDNotGeneratedException, \
    AttachFailed
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from ute_common_store.store import Store
from .android_operations import AndroidOperations
import traceback

MAX_ATTACH_RETRIES = 2
MAX_TIME_RETRIES = 60


logger = BackgroundLogger.Instance()


class Mobile(UE):
    """Mobile"""
    def __init__(self, dut, device_name, rat, ue_type, adb_id, band, ip_v4_or_6):
        self.rat = rat
        self.device_name = device_name
        self.ue_type = ue_type
        self.adb_id = adb_id
        self.ipv4_or_6 = ip_v4_or_6
        self.android_operations = AndroidOperations(self.rat, self.device_name,
                                                    self.adb_id, band, ip_v4_or_6)
        self.te_id = TeId(dut, self.rat)
        self.ue_ip = None
        self.store = Store()

    def attach(self, verify_teid=False, call_type='data'):
        """Attach"""
        # self.android_operations.change_band()
        if self.rat != 'gsm':
            return self._attach_lte_or_wcdma(verify_teid, call_type)
        else:
            return self._attach_gsm(call_type)

    def detach(self):
        """Detach"""
        self.android_operations.switch_aeroplane_mode_on()
        # self.android_operations.switch_aeroplane_mode_off()

    def call_start(self, call_type='data', device_section=None, profile=None, **kwargs):
        """Call start"""
        if call_type.lower() == 'data':
            if profile is None:
                raise ProfileNotPassedException
            # ue_ip, iperf_section, profile, ue_type, rat, device_name, adb_id='',
            # ipv4_or_6='ipv4', **kwargs):
            iperf = Iperf(self.ue_ip, device_section, profile, self.ue_type, self.rat, self.device_name,
                          self.adb_id, ipv4_or_6=self.ipv4_or_6, version=self.android_operations.version)
            self.store.add(iperf, alias=profile)
            iperf.start_data(profile)
        elif call_type.lower() == 'voice':
            self.android_operations.start_voice_call()

    def call_stop(self, call_type='data', profile=None):
        """Call stop"""
        if call_type.lower() == 'voice':
            self.android_operations.end_voice_call()
        elif call_type.lower() == 'data':
            if profile is None:
                raise ProfileNotPassedException
            iperf = self.store.get(alias=profile)
            throughput_fields = iperf.stop_data(profile)
            self.store.remove(alias=profile)
            return throughput_fields

    def ue_statistics(self):
        """UE statistics"""
        pass

    def _attach_lte_or_wcdma(self, verify_teid, call_type):
        if call_type.lower() == 'data':
            for retry_attempt in range(MAX_ATTACH_RETRIES):
                logger.info('Attach Attempt :: {0}\n'.format(retry_attempt))
                self.android_operations.select_apn()
                self.android_operations.switch_aeroplane_mode_on()
                if verify_teid:
                    initial_iwf_value = self.te_id.get_te_id()
                self.android_operations.switch_aeroplane_mode_off()
                try:
                    if verify_teid:
                        self.te_id.check_iwf_value_increased(initial_iwf_value)
                    self._attempt_to_get_ue_ip()
                    return self.ue_ip
                except (IpNotFoundException, TEIDNotGeneratedException) as err:
                    logger.info("Exception in attach mobile {}".format(err))
                    if retry_attempt == MAX_ATTACH_RETRIES - 1:
                        raise err
                    else:
                        continue
                except (Exception) as err:
                    logger.debug(traceback.format_exc())
                    logger.error("Exception while attach {}".format(err))
                    raise err
            raise AttachFailed('After {} tries'.format(MAX_ATTACH_RETRIES))
        elif call_type.lower() == 'voice':
            self.android_operations.switch_aeroplane_mode_on()
            self.android_operations.switch_aeroplane_mode_off()

    def _attempt_to_get_ue_ip(self):
        for time_attempt in range(MAX_TIME_RETRIES):
            try:
                self.ue_ip = self.android_operations.get_ue_ip()
                return
            except IpNotFoundException as e:
                sleep(5)
                if time_attempt == MAX_TIME_RETRIES - 1:
                    raise e
                else:
                    continue

    def _attach_gsm(self, call_type):
        self.android_operations.select_apn()
        self.android_operations.switch_aeroplane_mode_on()
        self.android_operations.switch_aeroplane_mode_off()
        if call_type.lower() == "data":
            sleep(10)
            self.ue_ip = self.android_operations.get_ue_ip()
            return self.ue_ip

    def get_network_parameter(self):
        """Get network parameter"""
        return self.android_operations.get_network_parameter()

    def configure_ue(self, **kwargs):
        """Configure UE"""
        command = kwargs.get('command')
        command = "sudo adb -s {{0}} shell su -c '{cmd}'".format(cmd=command)
        output = self.android_operations.execute_cmd(command)
        verify_command = kwargs.get('verify_command', '')
        if verify_command == '':
            return output
        verify_command = "sudo adb -s {{0}} shell su -c '{cmd}'".format(cmd=verify_command)
        wait_before_verify = kwargs.get('wait_before_verify', 2)
        sleep(wait_before_verify)
        output = self.android_operations.execute_cmd(verify_command)
        return output

    def call_teardown(self, **kwargs):
        """Call teardown"""
        pass
